function cosineSimilarity(a, b) {
  let dot = 0, magA = 0, magB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    magA += a[i] * a[i];
    magB += b[i] * b[i];
  }
  return dot / (Math.sqrt(magA) * Math.sqrt(magB));
}

function recallAtK(tests, search, k = 5) {
  let hits = 0;
  for (const t of tests) {
    const ids = search(t.question).slice(0, k).map(r => r.id);
    if (ids.includes(t.answerChunkId)) hits++;
  }
  return hits / tests.length;
}

